  laboratories: [
    {
      name: '1. Workshop Practice Lab',
      description: 'Equipped to fabricate carpentry components, plumbing piping networks, welding structural joints, sheet metal forming, centrifugal pump testing, air conditioning test rigs, smithy, foundry, and machine fitting. Well designed to accommodate 5 students per group with daily, weekly, and monthly maintenance cycles.',
      equipment: ['Carpentry Benches & Tools', 'Arc & Gas Welding Rigs', 'Plumbing & Pipe Threading Kits', 'Sheet Metal Forming Tools', 'Smithy Open Hearth Furnace', 'Foundry Moulding Sand Kits', 'Centrifugal Pump Test Setup', 'Air Conditioner Test Rig'],
      location: 'Mechanical Sciences Block - Ground Floor (Lab W101)',
    },
    {
      name: '2. Production Technology Laboratory',
      description: 'Used to study and practice operations in spot welding, plastic injection moulding, and universal sand testing machines (UTM) for sand casting analysis to acquire practical industry competencies. Machine tool lubrications and cutting tool sharpening follow rigorous weekly maintenance schedules.',
      equipment: ['Spot Resistance Welding Machine', 'Hydraulic Injection Moulding Machine', 'Universal Sand Testing Machine', 'Sand Sieve Shaker & Permeability Meter', 'Core Hardness Tester', 'Moulding Flasks & Patterns'],
      location: 'Manufacturing Block - Room 102',
    },
    {
      name: '3. Metallurgy Laboratory',
      description: 'Dedicated domain of materials science studying the physical and chemical microstructural behavior of metallic elements, inter-metallic compounds, and engineering alloys. Equipped with metallurgical microscopes, polishing disc machines, and muffle heat-treatment furnaces.',
      equipment: ['Trinocular Metallurgical Microscope', 'Double Disc Specimen Polishing Machine', 'Muffle Furnace (1200°C)', 'Jominy End Quench Apparatus', 'Standard Metallurgical Specimen Sets', 'Specimen Mounting Press'],
      location: 'Materials Research Wing - Room 103',
    },
    {
      name: '4. Metrology & Measurement Laboratory',
      description: 'Precision measurement and industrial quality inspection laboratory equipped with toolmaker microscopes, profile projectors, gear tooth calipers, sine bars, optical comparators, and surface roughness testers to perform quality assurance measurements.',
      equipment: ['Toolmaker’s Optical Microscope', 'Profile Projector 300mm Screen', 'Autocollimator with Angle Dekkor', 'Surface Roughness Tester', 'Gear Tooth Vernier Calipers', 'Sine Bar & Slip Gauge Sets', 'Floating Carriage Micrometer'],
      location: 'Quality Assurance Wing - Room 104',
    },
    {
      name: '5. Thermal Engineering Lab',
      description: 'State-of-the-art laboratory for studying valve timing diagrams, IC engine load/emission performance (4-stroke single/multi cylinder diesel & petrol engines), computer-interfaced data acquisition, exhaust gas calorimeters, steam turbine cycles, and vapor compression refrigeration units.',
      equipment: ['4-Stroke Multi-Cylinder Petrol Engine Test Rig', 'Single Cylinder 4-Stroke Diesel Engine Rig with DAQ', 'Variable Compression Ratio (VCR) Engine', 'Vapour Compression Refrigeration Test Rig', 'Air Conditioning Tutor Rig', 'Exhaust Gas Calorimeter & Smoke Meter'],
      location: 'Thermal Sciences Complex - Ground Floor',
    },
    {
      name: '6. Dynamics of Machinery Laboratory',
      description: 'Demonstrates principles of kinematics and dynamic mechanisms including governors, gyroscopic couple apparatus, static and dynamic balancing of rotating masses, whirling of shafts, cam analysis machine, and vibration test rigs.',
      equipment: ['Motorized Gyroscope Apparatus', 'Universal Governor Test Rig (Watt, Porter, Proell, Hartnell)', 'Static and Dynamic Balancing Machine', 'Whirling of Shaft Apparatus', 'Cam Analysis Machine with Stroboscope', 'Torsional Vibration Test Apparatus'],
      location: 'Mechanics & Vibration Wing - Room 106',
    },
    {
      name: '7. Machine Tools Laboratory',
      description: 'Equipped with heavy-duty all-geared engine lathes, shaping machines, slotting machines, radial drilling machines, vertical & horizontal milling machines, tool & cutter grinders, and CNC part manufacturing machines.',
      equipment: ['All-Geared Lathes (12 Units)', 'Shaping & Planing Machines', 'Universal Milling Machine', 'Vertical Machining Center (VMC)', 'Radial Drilling Machine', 'Tool & Cutter Grinder', 'Surface Grinding Machine'],
      location: 'Central Machining Center - Ground Floor',
    },
    {
      name: '8. Instrumentation and Control System Laboratory',
      description: 'Equipped with precision sensors, LVDT displacement transducers, thermocouple/RTD temperature transmitters, load cell calibrators, capacitive/inductive proximity sensors, and PID speed/position control systems for automated industrial quality inspection.',
      equipment: ['LVDT Displacement Measurement Setup', 'Strain Gauge & Load Cell Calibration Rig', 'Thermocouple, RTD & Thermistor Calibration Unit', 'Rotameter & Orifice Flow Transducer Setup', 'PID Speed Control System', 'Capacitive & Inductive Proximity Sensors'],
      location: 'Mechatronics Wing - Room 201',
    },
    {
      name: '9. Heat Transfer Lab',
      description: 'Provides fundamental and industrial practical training on conduction, convection, and radiation. Features Pin Fin Apparatus in forced/natural convection with embedded thermocouples, shell and tube heat exchanger, Stefan-Boltzmann radiation apparatus, and thermal conductivity test units.',
      equipment: ['Pin Fin Apparatus with Forced Convection Blower', 'Shell & Tube Heat Exchanger', 'Stefan-Boltzmann Radiation Apparatus', 'Thermal Conductivity of Metal Rod Apparatus', 'Emissivity Measurement Test Rig', 'Drop-wise & Film-wise Condensation Setup', 'Critical Heat Flux Apparatus'],
      location: 'Thermal Sciences Complex - First Floor',
    },
    {
      name: '10. Fuels Laboratory',
      description: 'Testing laboratory for measuring viscosity (Saybolt, Redwood, Engler), flash & fire point (Pensky-Martens, Abel, Cleveland), cloud & pour point, bomb calorimeter gross calorific value, and an automated pilot-scale esterification plant for biodiesel research.',
      equipment: ['Pensky-Martens Closed Cup Flash Point Tester', 'Redwood & Saybolt Viscometers', 'Bomb Calorimeter with Oxygen Regulator', 'Cloud & Pour Point Refrigerator Bath', 'Carbon Residue Apparatus (Conradson)', 'Pilot Esterification Biodiesel Synthesis Plant'],
      location: 'Alternative Fuels Research Center - Room 108',
    },
    {
      name: '11. CAD / CAM Laboratory',
      description: 'Advanced computing center equipped with 70 high-performance workstations connected to high-speed internet, projector facilities, 2D drafting/3D modeling suites (CATIA, SolidWorks, Autodesk Inventor), FEA/CFD analysis (ANSYS), and production CNC Lathe & CNC VMC with Siemens & Fanuc controllers.',
      equipment: ['70 Core i7 Workstations with Dedicated GPUs', 'Dassault CATIA & SolidWorks Modeling Suites', 'ANSYS Mechanical & CFD Simulation Licenses', 'Production CNC Lathe (Siemens 808D)', 'CNC Vertical Machining Center (Fanuc Series)', 'High-Resolution 3D Printing Station', 'E-Classroom Smart Interactive Board (R221)'],
      location: 'CAD/CAM Centre of Excellence - Room 221 & 222',
    },
  ],
